// Scope Chain for WITH statement
// ==================================================================

// MAX_SCOPE_DEPTH is defined in action_internal.h
ASObject* scope_chain[MAX_SCOPE_DEPTH];
u8 scope_is_with[MAX_SCOPE_DEPTH];       // 1 = with scope, 0 = function scope
MovieClip* scope_mc[MAX_SCOPE_DEPTH];     // non-NULL if scope entry is a MovieClip
u32 scope_depth = 0;

// Exception handling infrastructure (setjmp/longjmp based try/catch)
#define MAX_EXCEPTION_DEPTH 16

typedef struct {
	jmp_buf handler;
	int has_jmp_buf;
	u32 saved_scope_depth;
	u32 saved_sp;
} ExceptionFrame;

typedef struct {
	ExceptionFrame frames[MAX_EXCEPTION_DEPTH];
	int depth;

	bool exception_thrown;
	ActionVar exception_value;

	bool return_pending;
	ActionVar return_value;
} ExceptionState;

static ExceptionState g_exception_state = {0};

// Per-call-frame `this` binding stack (mirrors Ruffle's Activation.this)
// This is separate from the scope chain — GetVariable("this") checks this stack
// before the scope chain, matching Flash's behavior where `this` is not a scope property.
// MAX_THIS_DEPTH is defined in action_internal.h
ActionVar g_this_stack[MAX_THIS_DEPTH];
u32 g_this_depth = 0;

// Tracks the scope object on which the last GetVariable found a value via a WITH scope.
// Used by CallFunction to determine the correct `this` binding when a function is
// found on a scope chain entry (Ruffle: CallableValue::Callable(scope_obj, fn)).
// Reset to {.type = ACTION_STACK_VALUE_UNDEFINED} after each GetVariable call.
static ActionVar g_last_callable_this = {0};
static int g_last_callable_this_set = 0;
static int g_last_callable_this_is_with = 0;  // 1 if from a WITH scope entry

// Super context stack — tracks prototype chain depth for super() resolution.
// Ruffle model: super is a virtual (this, depth) pair. Depth indicates how many
// __proto__ levels to skip when resolving super properties/constructors.
// depth=1 means "start from this.__proto__" (i.e. the first parent class).
#define MAX_SUPER_DEPTH 64
static void* g_super_this_stack[MAX_SUPER_DEPTH];   // this binding for each super level (ASObject*)
static u8    g_super_depth_stack[MAX_SUPER_DEPTH];   // prototype chain depth
static void* g_super_mc_stack[MAX_SUPER_DEPTH];      // companion MovieClip* (for registerClass ctors)
static u32   g_super_stack_pos = 0;

static void pushSuperContext(void* this_obj, u8 depth) {
	if (g_super_stack_pos < MAX_SUPER_DEPTH) {
		g_super_this_stack[g_super_stack_pos] = this_obj;
		g_super_depth_stack[g_super_stack_pos] = depth;
		g_super_mc_stack[g_super_stack_pos] = NULL;
		g_super_stack_pos++;
	}
}

// Push super context with a companion MC pointer.
// Used by registerClass constructors where this_obj is mc->dynamic_props (for
// proto chain walking) but the parent constructor needs the actual MovieClip.
void pushSuperContextWithMC(void* this_obj, u8 depth, void* mc) {
	if (g_super_stack_pos < MAX_SUPER_DEPTH) {
		g_super_this_stack[g_super_stack_pos] = this_obj;
		g_super_depth_stack[g_super_stack_pos] = depth;
		g_super_mc_stack[g_super_stack_pos] = mc;
		g_super_stack_pos++;
	}
}

void popSuperContext(void) {
	if (g_super_stack_pos > 0) g_super_stack_pos--;
}

static int hasSuperContext(void) {
	return g_super_stack_pos > 0;
}

static void* getSuperThis(void) {
	return g_super_stack_pos > 0 ? g_super_this_stack[g_super_stack_pos - 1] : NULL;
}

static u8 getSuperDepth(void) {
	return g_super_stack_pos > 0 ? g_super_depth_stack[g_super_stack_pos - 1] : 0;
}

// Returns the companion MC if the super context was created by a registerClass constructor.
static void* getSuperMC(void) {
	return g_super_stack_pos > 0 ? g_super_mc_stack[g_super_stack_pos - 1] : NULL;
}

// Forward declare resolveProtoVar (defined below walkProtoChain)
void* resolveProtoVar(ActionVar* proto_var);

// Walk the __proto__ chain from 'this_obj' by 'depth' levels.
// Returns the prototype object at that depth, or NULL if chain is too short.
static ASObject* walkProtoChain(void* this_obj, u8 depth) {
	if (this_obj == NULL) return NULL;
	ASObject* current = (ASObject*) this_obj;
	for (u8 i = 0; i < depth; i++) {
		ActionVar* proto_var = getProperty(current, "__proto__", 9);
		current = (ASObject*) resolveProtoVar(proto_var);
		if (current == NULL) return NULL;
	}
	return current;
}

// Resolve a __proto__ ActionVar to an ASObject* (returned as void*).
// OBJECT → direct cast. ARRAY → arr->props (the array's string-keyed property
// bag, whose own __proto__ points at Array.prototype). SUPER → unwrap by
// walking this_ptr's proto chain.
void* resolveProtoVar(ActionVar* proto_var) {
	if (proto_var == NULL || proto_var->data.numeric_value == 0) return NULL;
	if (proto_var->type == ACTION_STACK_VALUE_OBJECT)
		return (void*) proto_var->data.numeric_value;
	if (proto_var->type == ACTION_STACK_VALUE_ARRAY) {
		ASArray* arr = (ASArray*) proto_var->data.numeric_value;
		return (arr != NULL) ? (void*) arr->props : NULL;
	}
	if (proto_var->type == ACTION_STACK_VALUE_SUPER)
		return (void*) walkProtoChain((void*) proto_var->data.numeric_value, (u8) proto_var->str_size);
	return NULL;
}

// Get the "super proto" — the prototype where super methods are searched.
// This is this.__proto__^depth (i.e., walk depth levels up).
static ASObject* getSuperBaseProto(void) {
	if (g_super_stack_pos == 0) return NULL;
	void* this_obj = g_super_this_stack[g_super_stack_pos - 1];
	u8 depth = g_super_depth_stack[g_super_stack_pos - 1];
	return walkProtoChain(this_obj, depth);
}

// Get the prototype of the base proto — where super property/method searches start.
// This is this.__proto__^(depth+1).
static ASObject* getSuperSearchStart(void) {
	ASObject* base = getSuperBaseProto();
	if (base == NULL) return NULL;
	ActionVar* proto_var = getProperty(base, "__proto__", 9);
	return (ASObject*) resolveProtoVar(proto_var);
}

// Forward declarations for MC property helpers (defined in WITH section)
static int getMCBuiltinProperty(MovieClip* mc, const char* name, u32 name_len, ActionVar* result);
static int setMCBuiltinProperty(SWFAppContext* app_context, MovieClip* mc, const char* name, u32 name_len, ActionVar* value);
static void applyInitObjectPropToMC(SWFAppContext* app_context, MovieClip* mc, const char* name, u32 name_len, ActionVar* value);

// Stored app_context for use by setVariableOnLocalScope (called from variables.c
// which doesn't have app_context). Set at entry to actionCallFunction/actionCallMethod.
static SWFAppContext* g_scope_app_context = NULL;

// Set to the receiver ASObject whenever a C function (advanced_func) is called
// as an object method via actionCallMethod. Used by AsBroadcaster methods to
// identify which object they are operating on.
static ASObject* g_c_function_this_obj = NULL;

// Tracks the ActionVar type tag of the current `this` object when calling
// advanced_func. Used by builtin_array_method to know if this_obj is an ASArray*.
static int g_current_this_type = 0;

// Expose local scope for parameter binding (used by setVariableByName)
// Skips 'with' scopes to find the nearest function scope.
ASObject* getCurrentLocalScope(void)
{
	for (int i = scope_depth - 1; i >= 0; i--)
	{
		if (!scope_is_with[i] && scope_chain[i] != NULL)
			return scope_chain[i];
	}
	return NULL;
}

// Try to set a variable on the current local scope (function scope).
// Returns true if we're inside a function and the variable was set on local scope.
// Returns false if no local scope exists (caller should fall through to global).
bool setVariableOnLocalScope(const char* var_name, ActionVar* value)
{
	ASObject* local_scope = getCurrentLocalScope();
	if (local_scope == NULL)
		return false;

	u32 name_len = strlen(var_name);

	// Use setProperty which properly allocates with HALLOC (matching releaseObject's FREE)
	setProperty(g_scope_app_context, local_scope, var_name, name_len, value);
	return true;
}

