// global or its construction. avm1/native_objects_swf6 line 56 (Flash
// capture, known_failure upstream) wants `new TextField()` -> undefined at
// SWF 6, but avm1/textfield_props_swf6 (Ruffle-passing) and the gnash
// TextField-v5 / toString_valueOf-v5/v6 Ruffle oracles all pin an OBJECT at
// v5/v6 — the upstream corpus contradicts itself, and satisfying that one
// line costs seven tests. See ACCEPTED_DIFFS.md "native_objects_swf6".

int g_main_movie_swf_version = 5;  // Main movie's SWF version — set once by main.c, never
                                   // swapped during child-SWF/import context switches. Used
                                   // for root_movieclip.swf_version so getSWFVersion() on
                                   // _root reports the right value even when ensureGlobalInit
                                   // happens to first run inside an ImportAssets context.
float g_soundbuftime = 5.0f; // _soundbuftime — stage-wide property (per-root, not per-MC)
char g_stage_quality[16] = "HIGH"; // _quality / _highquality — stage-wide, not per-MC
int g_use_network = 0;       // UseNetwork flag from FileAttributes tag
u32 g_max_call_depth = 256;  // Default; overridden by tagScriptLimits()
u8 g_execution_halted = 0;   // Set when recursion limit is hit; halts all further script execution

// --- Execution timeout mechanism ---
// Mirrors Ruffle's max_execution_duration: checks wall-clock time every N actions
// and halts all script execution if the limit is exceeded.
#include <time.h>
static u32 g_actions_since_timeout_check = 0;
static double g_max_execution_ms = 0;  // 0 = no limit
static struct timespec g_execution_start_time;
static int g_execution_timer_active = 0;

void actionSetMaxExecutionDuration(double ms)
{
	g_max_execution_ms = ms;
}

void actionResetExecutionTimer(void)
{
	if (g_max_execution_ms > 0) {
		clock_gettime(CLOCK_MONOTONIC, &g_execution_start_time);
		g_execution_timer_active = 1;
		g_actions_since_timeout_check = 0;
	}
}

// Global longjmp target for timeout abort — set in swfStart before frame loop
#include <setjmp.h>
static jmp_buf g_timeout_jmp_buf;
static int g_timeout_jmp_active = 0;

static inline void actionCheckExecutionTimeout(void)
{
	if (!g_execution_timer_active) return;
	g_actions_since_timeout_check++;
	if (g_actions_since_timeout_check < 2000) return;
	g_actions_since_timeout_check = 0;

	struct timespec now;
	clock_gettime(CLOCK_MONOTONIC, &now);
	double elapsed_ms = (now.tv_sec - g_execution_start_time.tv_sec) * 1000.0 +
	                     (now.tv_nsec - g_execution_start_time.tv_nsec) / 1000000.0;
	if (elapsed_ms >= g_max_execution_ms) {
		g_execution_halted = 1;
		g_execution_timer_active = 0;
		// longjmp back to the frame loop to cleanly exit all script execution
		if (g_timeout_jmp_active) {
			longjmp(g_timeout_jmp_buf, 1);
		}
	}
}

void actionSetTimeoutJmp(void* jmp_buf_ptr)
{
	if (jmp_buf_ptr) {
		memcpy(g_timeout_jmp_buf, jmp_buf_ptr, sizeof(jmp_buf));
		g_timeout_jmp_active = 1;
	} else {
		g_timeout_jmp_active = 0;
	}
}
u32 g_call_depth = 0;
// >0 while inside an AS2 MC event handler dispatched via mc_call_as2_handler_ng
// (input-pump mouse events, focus events, deferred onChanged, etc. — all fire
// AFTER the per-tick funcs[current_frame] returned). Read by actionNextFrame /
// actionGotoFrame to run inline catch-up so the new frame's DoAction executes
// before the next event in the same tick. Mirrors Ruffle's synchronous
// MovieClip.nextFrame / gotoFrame semantics. Key test: ButtonEventsTest.
int g_inside_event_handler = 0;
// >0 while inside a Key/Mouse *broadcaster* callback (Key.addListener /
// Mouse.addListener listeners, dispatched through
// builtin_broadcaster_broadcastMessage from actionDispatchKeyDown/Up and
// actionDispatchMouseDown/Up/Move). Those never go through
// mc_call_as2_handler_ng, so g_inside_event_handler stays 0 for them — which
// silently dropped a nextFrame() issued from such a callback on a STOPPED
// root (w2-avm1-events G3). Read by actionNextFrame only.
// Key test: from_gnash/misc-ming.all/masks_test.
int g_inside_broadcaster_dispatch = 0;
static int g_child_swf_init = 0;  // >0 during child SWF init (MCL/loadMovie); scopes funcs to MC
extern u8 g_current_movie_id;    // Defined in tag_stubs.c — tracks which movie is currently initializing
static int g_use_new_invalid_bounds = 0;  // Ruffle: one-way flag, flips to 1 when getBounds/getRect called from SWF>=8

// EFFECTIVE_SWF_VERSION() is defined in actionmodern/action_internal.h
// so subsystem files carved out of action.c can use it too.

// ==================================================================
// Special Recursion Counter (LocalConnection/NetStream dispatch etc.)
// ==================================================================
// Non-fatal recursion bound for internal callback dispatch (drops the call
// instead of halting execution). NOTE: addProperty getter/setter invocations
// no longer use this — they count toward g_call_depth/g_max_call_depth (the
// ScriptLimits bound; exceeding it halts the script like Flash) and are
// re-entry-limited per addProperty entry (see invokeVirtualGetter/Setter).

#define MAX_SPECIAL_DEPTH 66
static u32 g_special_depth = 0;

// Flash-parity accessor/function recursion (up to g_max_call_depth = 256
// nested invocations before script death) can stack ~64KB interpreter frames
// (actionGetMember/actionSetMember are huge), overflowing the default 8MB
// main-thread stack around ~130 deep. Raise the soft RLIMIT_STACK at program
// start — the Linux kernel consults the current limit on each stack-growth
// fault, so the already-running main thread gains the headroom.
// (WASM builds instead use -sSTACK_SIZE in build scripts.)
#if !defined(__EMSCRIPTEN__) && (defined(__linux__) || defined(__APPLE__))
#include <sys/resource.h>
__attribute__((constructor))
static void raiseStackLimitForScriptRecursion(void)
{
	struct rlimit rl;
	if (getrlimit(RLIMIT_STACK, &rl) == 0)
	{
		rlim_t want = (rlim_t)64 * 1024 * 1024;
		if (rl.rlim_cur != RLIM_INFINITY && rl.rlim_cur < want)
		{
			rl.rlim_cur = (rl.rlim_max == RLIM_INFINITY || rl.rlim_max > want) ? want : rl.rlim_max;
			setrlimit(RLIMIT_STACK, &rl);
		}
	}
}
#endif

// ------------------------------------------------------------------
// addProperty getter/setter re-entrancy guard.
//
// When an addProperty getter for property P on object O reads P on O
// again (e.g. `function get() { return this.P; }`), Flash does NOT
// recurse indefinitely. In SWF6 the re-entrant access resolves to the
// property's underlying stored value after a single getter invocation;
// in SWF7+ Flash recurses 65 times before bottoming out at the
// underlying value (a documented Flash quirk — Gnash's Object.as marks
// the SWF7+ count `xcheck_equals(..., 65) // urgh!`).
//
// The re-entrancy key is version-specific (both counted on one LIFO stack):
//   SWF6:  per (receiver object, property name, getter-vs-setter) — one
//          invocation per chain, then the underlying value.
//   SWF7+: per addProperty ENTRY (the registration slot, keyed by
//          ASProperty::vprop_id), getter and setter invocations COMBINED,
//          65 per chain. Two receivers delegating to the same proto entry
//          share one counter (virtual_property_recursion_scope o1/o2 via p:
//          65 total); two entries recursing into each other get 65 each
//          (double_swf7: 130); delete + re-addProperty creates a fresh slot
//          and therefore a fresh counter (scope o6: unbounded, bottoms out
//          at the g_max_call_depth script-death backstop in the invokers).
// Sized above the deepest legal nesting: g_max_call_depth (256) accessor
// frames can be live before the invoker backstop halts the script.
#define MAX_ACTIVE_ACCESSORS 320
typedef struct {
	void* this_obj;
	u32 name_len;
	u32 entry_id;
	u8 is_setter;
	char name[64];
} ActiveAccessor;
static ActiveAccessor g_active_accessors[MAX_ACTIVE_ACCESSORS];
static u32 g_active_accessor_count = 0;

// Monotonic id source for ASProperty::vprop_id (0 = unassigned).
static u32 g_vprop_id_seq = 0;
static u32 vpropEntryId(ASProperty* prop)
{
	if (prop->vprop_id == 0) prop->vprop_id = ++g_vprop_id_seq;
	return prop->vprop_id;
}

static int countActiveAccessor(void* this_obj, const char* name, u32 name_len, u8 is_setter)
{
	int c = 0;
	u32 n = g_active_accessor_count < MAX_ACTIVE_ACCESSORS ? g_active_accessor_count : MAX_ACTIVE_ACCESSORS;
	for (u32 i = 0; i < n; i++)
	{
		ActiveAccessor* a = &g_active_accessors[i];
		if (a->this_obj == this_obj && a->is_setter == is_setter &&
		    a->name_len == name_len && memcmp(a->name, name, name_len) == 0)
			c++;
	}
	return c;
}

static int countActiveAccessorEntry(u32 entry_id)
{
	int c = 0;
	u32 n = g_active_accessor_count < MAX_ACTIVE_ACCESSORS ? g_active_accessor_count : MAX_ACTIVE_ACCESSORS;
	for (u32 i = 0; i < n; i++)
		if (g_active_accessors[i].entry_id == entry_id)
			c++;
	return c;
}

static void pushActiveAccessor(void* this_obj, const char* name, u32 name_len, u8 is_setter, u32 entry_id)
{
	// Count past capacity (records beyond MAX are dropped but the depth stays
	// balanced with popActiveAccessor — an unbalanced silent drop would make
	// pops eat other frames' records and the counters lose track entirely).
	if (g_active_accessor_count++ >= MAX_ACTIVE_ACCESSORS) return;
	ActiveAccessor* a = &g_active_accessors[g_active_accessor_count - 1];
	a->this_obj = this_obj;
	a->is_setter = is_setter;
	a->entry_id = entry_id;
	a->name_len = name_len < 63 ? name_len : 63;
	memcpy(a->name, name, a->name_len);
	a->name[a->name_len] = 0;
}

static void popActiveAccessor(void)
{
	if (g_active_accessor_count > 0) g_active_accessor_count--;
}

// Re-entry count at which the accessor invocation is replaced by the
// property's underlying value: 1 for SWF6 (one invocation, then
// underlying), 65 for SWF7+ (Flash's quirky deep-recursion count).
static int accessorReentryLimit(void)
{
	return (g_swf_version <= 6) ? 1 : 65;
}

// Centralized addProperty accessor dispatch (guard + invoke + fallback).
// All virtual-property getter/setter invocations should go through these so
// the re-entrancy rules above apply uniformly on every dispatch path
// (GetMember/SetMember, GetVariable/SetVariable scope walks, MC dprops, ...).
static ActionVar invokeVirtualGetter(SWFAppContext* app_context, ASProperty* prop, void* this_obj);
static void invokeVirtualSetter(SWFAppContext* app_context, ASProperty* prop, void* this_obj, ActionVar* value);

