// Set when GetMember on a FUNCTION returns call/apply; consumed by the
// empty-method-name path in CallMethod.
static ASFunction* g_getmember_call_target = NULL;

// --- Object.prototype.watch() / unwatch() watcher table ---
#define MAX_WATCH_ENTRIES 64
typedef struct {
	ASObject* obj;          // NULL for timeline/MovieClip variable watches
	MovieClip* mc;          // Non-NULL for timeline variable watches (obj==NULL)
	char prop_name[64];
	u32 prop_name_len;
	ASFunction* watcher_func;
	ActionVar user_data;    // userData (3rd arg passed to watch())
} WatchEntry;
static WatchEntry g_watch_table[MAX_WATCH_ENTRIES];
static int g_watch_count = 0;

// Re-entrancy guard for watch handlers. Setting a watched property from inside
// its own watch handler re-fires the handler a Flash-version-specific number of
// times: SWF6 invokes it once then commits the value without re-firing; SWF7+
// recurses 65 levels before bottoming out — the same quirky depth Flash uses
// for addProperty getter/setter re-entry (see accessorReentryLimit()). Ruffle
// recurses unboundedly (its watch_special_recursion tests are known_failure);
// without this bound we recurse on the C stack and segfault. A LIFO stack of
// the currently-firing (obj/mc, prop) pairs (counting nested matches) mirrors
// the g_active_accessors model and is robust to the watch table being reordered
// by unwatch() inside a handler.
// Sized above the deepest legal nesting (one entry per re-fire; the double
// tests reach accessorReentryLimit()==65 on each of two distinct props → 130).
// If this fills, pushes silently drop and the depth guard would stop counting
// (→ runaway recursion), so it must comfortably exceed the worst case.
#define MAX_WATCH_FIRING 256
static struct { ASObject* obj; MovieClip* mc; char prop[64]; u32 len; } g_watch_firing[MAX_WATCH_FIRING];
static int g_watch_firing_count = 0;
static int watch_firing_depth(ASObject* obj, MovieClip* mc, const char* prop, u32 len) {
	int c = 0;
	for (int i = 0; i < g_watch_firing_count; i++)
		if (g_watch_firing[i].obj == obj && g_watch_firing[i].mc == mc &&
		    g_watch_firing[i].len == len && strncmp(g_watch_firing[i].prop, prop, len) == 0)
			c++;
	return c;
}
static void watch_firing_push(ASObject* obj, MovieClip* mc, const char* prop, u32 len) {
	if (g_watch_firing_count >= MAX_WATCH_FIRING) return;
	u32 c = len < (u32)(sizeof(g_watch_firing[0].prop) - 1) ? len : (u32)(sizeof(g_watch_firing[0].prop) - 1);
	g_watch_firing[g_watch_firing_count].obj = obj;
	g_watch_firing[g_watch_firing_count].mc = mc;
	memcpy(g_watch_firing[g_watch_firing_count].prop, prop, c);
	g_watch_firing[g_watch_firing_count].prop[c] = '\0';
	g_watch_firing[g_watch_firing_count].len = len;
	g_watch_firing_count++;
}
static void watch_firing_pop(void) {
	if (g_watch_firing_count > 0) g_watch_firing_count--;
}
// Receiver-keyed variant: counts firing entries for `recv` on EITHER slot (the
// object site pushes (obj, NULL), the MC/timeline sites push (NULL, mc)), so an
// accessor dispatch — which only ever holds one opaque receiver pointer — can
// read the watch half of the shared per-property re-entry counter. See the
// "unified special-access counter" note above virtualAccessorBlocked().
// NULL receiver returns 0 (never let a NULL this_obj alias the mc-keyed rows).
static int watch_firing_depth_recv(const void* recv, const char* prop, u32 len) {
	if (recv == NULL || prop == NULL) return 0;
	int c = 0;
	for (int i = 0; i < g_watch_firing_count; i++)
		if (((const void*)g_watch_firing[i].obj == recv || (const void*)g_watch_firing[i].mc == recv) &&
		    g_watch_firing[i].len == len && strncmp(g_watch_firing[i].prop, prop, len) == 0)
			c++;
	return c;
}
// Total nesting cap for watch re-fire, the non-fatal backstop that keeps a
// runaway handler off the C stack. Flash's own legal depth on the mutually
// recursive "double" tests is 130 (accessorReentryLimit() == 65 on each of two
// distinct properties), so this must sit above that — it used to be
// MAX_SPECIAL_DEPTH (66), which truncated watch_recursion_double_swf7 at half
// its output. The 8MB-main-stack worry that motivated 66 is gone: the
// RLIMIT_STACK constructor above raises the soft limit to 64MB and the
// virtual_property_recursion family already recurses 130 deep through the same
// interpreter frames. Must stay <= MAX_WATCH_FIRING (pushes past that silently
// drop and would stop the depth guard from counting).
#define MAX_WATCH_NESTING 200
// Shared re-entry check for the three watch dispatch sites (object SetMember,
// timeline SetVariable, MovieClip SetMember). Returns nonzero when the handler
// must NOT re-fire and the value is committed directly instead.
//
// The first term is the watch half of the unified special-access counter, the
// second the addProperty half — see the block comment above
// virtualAccessorBlocked() for the model and the Flash-oracle derivation. The
// accessor half is keyed by (receiver, name) rather than by vprop entry id
// because the dispatch sites hold a receiver, not an ASProperty; the two keys
// only diverge when one proto entry is shared by several receivers, and a
// watcher is registered per receiver anyway.
static int watchReentryBlocked(ASObject* obj, MovieClip* mc, const char* prop, u32 len)
{
	if (g_watch_firing_count >= MAX_WATCH_NESTING) return 1;
	void* recv = (obj != NULL) ? (void*)obj : (void*)mc;
	int accessor_nesting = 0;
	if (recv != NULL && len <= 63)
		accessor_nesting = countActiveAccessor(recv, prop, len, 0) +
		                   countActiveAccessor(recv, prop, len, 1);
	return watch_firing_depth(obj, mc, prop, len) + accessor_nesting >= accessorReentryLimit();
}

// Object.registerClass(symbolName, constructorFunc)
// Returns true on success, false on invalid args.
static ActionVar actionObjectRegisterClass(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void)registers; (void)this_obj;
	ActionVar result = {0};
	result.type = ACTION_STACK_VALUE_BOOLEAN;

	// Need at least 2 args
	if (arg_count < 2)
	{
		result.data.numeric_value = 0; // false
		return result;
	}

	// Coerce first arg (symbol name) to string via the stack
	pushVar(app_context, &args[0]);
	char _rc_buf[17];
	convertString(app_context, _rc_buf);
	char symbol_buf[256];
	u32 sym_len = (u32)u16_to_utf8((const uint16_t*)STACK_TOP_VALUE, STACK_TOP_N, symbol_buf, sizeof(symbol_buf) - 1);
	symbol_buf[sym_len] = '\0';
	POP();

	// Second arg: null/undefined = unregister, function = register, anything else = false
	if (args[1].type == ACTION_STACK_VALUE_NULL || args[1].type == ACTION_STACK_VALUE_UNDEFINED)
	{
		// Unregister
		actionRegisterClassForSymbol(symbol_buf, NULL);
		result.data.numeric_value = 1; // true
		return result;
	}

	if (args[1].type != ACTION_STACK_VALUE_FUNCTION)
	{
		result.data.numeric_value = 0; // false
		return result;
	}

	ASFunction* ctor = (ASFunction*)(uintptr_t)args[1].data.numeric_value;
	actionRegisterClassForSymbol(symbol_buf, (void*)ctor);
	result.data.numeric_value = 1; // true
	return result;
}

// Built-in toString for Object(primitive) wrappers — returns valueOf as string
static ActionVar builtin_wrapper_toString(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	ActionVar ret;
	ret.type = ACTION_STACK_VALUE_STRING;
	ret.str_size = 15;
	ret.data.numeric_value = (u64) u16_object_Object;

	if (this_obj != NULL)
	{
		ASObject* obj = (ASObject*) this_obj;
		ActionVar* val_prop = getProperty(obj, "valueOf", 7);
		if (val_prop != NULL && val_prop->type != ACTION_STACK_VALUE_FUNCTION)
		{
			char buf[64];
			int len = varToStringBuf(app_context, val_prop, buf, sizeof(buf));
			// Convert UTF-8 result to UTF-16 for storage
			u32 u16_len;
			uint16_t* u16_str = ascii_to_u16(app_context, buf, len, &u16_len);
			ret.data.string_data.heap_ptr = u16_str;
			ret.data.string_data.owns_memory = true;
			ret.str_size = u16_len;
		}
	}
	return ret;
}

static ActionVar builtin_object_toString(SWFAppContext* app_context)
{
	ActionVar ret;
	ret.type = ACTION_STACK_VALUE_STRING;
	if (g_swf_version < 5) {
		// SWF4 and below uses "[type Object]" format for user-created objects
		ret.str_size = 13;
		ret.data.numeric_value = (u64) u16_type_Object;
	} else {
		// SWF5+ uses "[object Object]" format
		ret.str_size = 15;
		ret.data.numeric_value = (u64) u16_object_Object;
	}
	return ret;
}

// --- Stub class toString (always "[type Object]" regardless of SWF version) ---
// Used for stub class instances (PrintJob, etc.) which trace as "[type Object]" in SWF < 7,
// overriding the Object.prototype.toString that would otherwise return "[object Object]".
static ActionVar builtin_type_object_toString(SWFAppContext* app_context)
{
	ActionVar ret;
	ret.type = ACTION_STACK_VALUE_STRING;
	ret.str_size = 13;
	ret.data.numeric_value = (u64) u16_type_Object;
	return ret;
}

static ASFunction g_type_object_toString_func;

// --- Native object toString (always "[object Object]" regardless of SWF version) ---
// Used for static native objects (Math, Key, Mouse, Stage, etc.) which always trace
// as "[object Object]" even in SWF5, unlike user-created objects.
static ActionVar builtin_native_object_toString(SWFAppContext* app_context)
{
	ActionVar ret;
	ret.type = ACTION_STACK_VALUE_STRING;
	ret.str_size = 15;
	ret.data.numeric_value = (u64) u16_object_Object;
	return ret;
}

static ASFunction g_native_toString_func;
static int g_native_toString_init = 0;

// Install a toString method that always returns "[object Object]" on a native ASObject.
// This bypasses Object.prototype.toString's SWF version check.
void installNativeToString(SWFAppContext* app_context, ASObject* obj)
{
	if (!g_native_toString_init) {
		memset(&g_native_toString_func, 0, sizeof(ASFunction));
		strncpy(g_native_toString_func.name, "toString", 255);
		g_native_toString_func.function_type = 1;
		g_native_toString_func.simple_func = (SimpleFunctionPtr) builtin_native_object_toString;
		if (function_count < MAX_FUNCTIONS)
			function_registry[function_count++] = &g_native_toString_func;
		g_native_toString_init = 1;
	}
	ActionVar ts_var = {0};
	ts_var.type = ACTION_STACK_VALUE_FUNCTION;
	ts_var.data.numeric_value = (u64) &g_native_toString_func;
	setPropertyWithFlags(app_context, obj, "toString", 8, &ts_var, PROPERTY_FLAGS_DONTENUM);
}

