/**
 * Create a new MovieClip with the specified instance name and parent
 *
 * @param instance_name The name of this MovieClip instance (e.g., "mc1")
 * @param parent The parent MovieClip (can be NULL for orphaned clips)
 * @return Pointer to the newly allocated MovieClip
 *
 * Note: The caller is responsible for freeing the returned MovieClip
 */
static MovieClip* createMovieClip(const char* instance_name, MovieClip* parent) {
	// calloc zero-initializes every field. Fields that need a non-zero default
	// are set explicitly below; adding a new field to struct MovieClip is
	// automatically safe (zero) without a matching update here. Previously
	// malloc+partial-init left `loaded_image_{width,height}` (and other newer
	// fields) uninitialized, which mcGetOriginalBounds read on the first
	// branch — manifesting as non-deterministic _width/_height on dynamic MCs
	// whenever the surrounding heap layout shifted.
	MovieClip* mc = (MovieClip*)calloc(1, sizeof(MovieClip));
	if (!mc) {
		return NULL;
	}

	mc->xscale = 100.0f;
	mc->yscale = 100.0f;
	mc->alpha = 100.0f;
	mc->visible = 1;
	mc->currentframe = 1;
	mc->totalframes = 1;
	mc->framesloaded = 1;
	mc->highquality = 1.0f;
	mc->focusrect = -1.0f;   // -1.0f sentinel = null
	mc->soundbuftime = 5.0f;
	strcpy(mc->quality, "HIGH");
	// Inherit URL from parent (or root); overridden by createEmptyMovieClip/loadMovie
	if (parent != NULL && parent->url[0] != '\0') {
		strncpy(mc->url, parent->url, sizeof(mc->url) - 1);
	} else {
		extern MovieClip root_movieclip;
		if (root_movieclip.url[0] != '\0') {
			strncpy(mc->url, root_movieclip.url, sizeof(mc->url) - 1);
		}
	}
	// Inherit SWF version from parent; overridden by loadMovie
	mc->swf_version = parent ? parent->swf_version : (u16)g_swf_version;
	mc->ng_textfield_idx = -1;
	// Color transform defaults for dynamic MCs
	mc->cx_ra = 100.0f; mc->cx_ga = 100.0f; mc->cx_ba = 100.0f; mc->cx_aa = 100.0f;

	// Set instance name
	strncpy(mc->name, instance_name, sizeof(mc->name) - 1);
	mc->name[sizeof(mc->name) - 1] = '\0';

	// Set parent and construct target path
	mc->parent = parent;

	// Construct target path based on parent
	if (parent == NULL) {
		// No parent - standalone clip
		strncpy(mc->target, instance_name, sizeof(mc->target) - 1);
		mc->target[sizeof(mc->target) - 1] = '\0';
	} else {
		// Has parent - construct target path using / separator (Flash uses slash-path format)
		int parent_len = strlen(parent->target);
		int written;
		if (parent_len == 1 && parent->target[0] == '/') {
			// Parent is root "/" — child target is "/childName"
			written = snprintf(mc->target, sizeof(mc->target), "/%s", instance_name);
		} else {
			written = snprintf(mc->target, sizeof(mc->target), "%s/%s",
			                   parent->target, instance_name);
		}
		if (written >= (int)sizeof(mc->target)) {
			mc->target[sizeof(mc->target) - 1] = '\0';
		}
	}

	// Save original target path (used for removed MC toString — never updated by _name changes)
	strncpy(mc->original_target, mc->target, sizeof(mc->original_target));
	mc->original_target[sizeof(mc->original_target) - 1] = '\0';

	return mc;
}

// MovieClip cache: ensures same instance name always returns same pointer
// so properties (dynamic_props) persist across lookups. When this cache is
// FULL, findOrCreateMovieClip can no longer cache a freshly-created MC, so
// every subsequent name lookup (GetVariable/GetMember) mints a *brand-new*
// MovieClip with empty dynamic_props — breaking `parent[childName]` resolution
// for attachMovie'd children (whose binding lives on the attach-time instance's
// dynamic_props). 128 was too small for games that attach many clips: Tetris
// builds a ~118-cell board via b_mc.attachMovie("block",...), then colors cells
// with b_mc[pos].gotoAndStop(c) every tick — with a 128 cap the board cells fill
// the cache, b_mc/next_mc become uncacheable, their dynamic_props never persist,
// and every gotoAndStop hit an undefined receiver (blank board + falling piece).
// 512 comfortably holds the board + next-piece preview + UI clips. The cap is a
// leak backstop only (per-tick MC leaks are prevented at their source, e.g. the
// browser-WASM frame-func re-run guard in tag.c), so raising it does not change
// correctness for churny games — it only adds headroom.
// 1024: a single Minesweeper board is 30*16=480 duplicateMovieClip cells, which
// alongside the game/menu chrome MCs exceeds the old 512 cap (the last ~22 cells
// were dropped → a partly-blank board). The add path below also reuses NULL
// (removed) slots so deleteCells+rebuild on Restart doesn't grow the table.
// 4096 (was 1024): tile-heavy games saturate the cache with their own live
// clips, after which later-created clips can't register — so their AS2 button
// handlers (onPress/onRelease/onRollOver) are never hit-tested and parent[child]
// / dynamic-prop lookups return undefined. Metanet's "N" places a 31×23 = 713-
// cell tilemap plus a ~30-part demo ninja and particle effects that run behind
// the main menu, filling all 1024 slots before the menu's button clips are
// placed — so the menu was completely unclickable. The dispatch/enumeration
// loops iterate `child_mc_count` (the live high-water mark), not this cap, so a
// larger ceiling costs nothing for the vast majority of content that stays well
// under it. See memory `child-mc-cache-cap-resolution` (prior 128→512→1024 raises).
#define MAX_CHILD_MOVIECLIPS 16384
MovieClip* child_mc_cache[MAX_CHILD_MOVIECLIPS];
int child_mc_count = 0;
// MCs at index >= this threshold were just placed in the current frame's
// process_sprite_needs_init and should not fire onEnterFrame until next frame.
int g_enterframe_new_mc_start = -1;  // -1 = no skip
// Root MC enterFrame does not fire on the first tick (first tick fires LOAD/frame script).
// Set to true after the first tagShowFrame completes.
int g_root_enterframe_eligible = 0;

// _level management: _level0 is always root_movieclip.
// Higher levels are synthetic MCs created by loadMovieNum/loadClip.
#define MAX_LEVELS 128
MovieClip* g_levels[MAX_LEVELS];  // g_levels[0] = &root_movieclip, set in ensureGlobalInit
// Highest N for which g_levels[N] has ever been minted (0 = none). Bounds the
// level scans below so content that never calls loadMovieNum pays nothing.
static int g_levels_high_water = 0;

// A _levelN (N > 0) root owns a SYNTHETIC DisplayObject (allocated lazily in
// actionFirePendingDirectLoads' is_level branch) that lives in no display list,
// so set_enterframe_eligible_recursive never reaches it. Callers that gate on
// `display_obj->enterframe_eligible` must route level roots through the
// dynamic-MC gate (mc_enterframe_eligible) instead. Cheap: the loop body is a
// pointer compare and the bound is 0 for content without levels.
int actionIsLoadedLevelRootMC(MovieClip* mc)
{
	if (mc == NULL) return 0;
	for (int i = 1; i <= g_levels_high_water; i++)
		if (g_levels[i] == mc) return 1;
	return 0;
}

static MovieClip* getOrCreateLevel(SWFAppContext* app_context, int level_num) {
    if (level_num < 0 || level_num >= MAX_LEVELS) return NULL;
    if (level_num == 0) {
        return &root_movieclip;
    }
    if (g_levels[level_num] != NULL) return g_levels[level_num];
    // Create a new synthetic MC for this level
    MovieClip* mc = (MovieClip*)HCALLOC(1, sizeof(MovieClip));
    snprintf(mc->name, sizeof(mc->name), "_level%d", level_num);
    snprintf(mc->target, sizeof(mc->target), "_level%d", level_num);
    strncpy(mc->original_target, mc->target, sizeof(mc->original_target));
    mc->depth = level_num - 16384;
    // HCALLOC zeros ng_textfield_idx, but `0` means "static textfield #0",
    // making MC_IS_TEXTFIELD evaluate true. Mark as not-a-textfield.
    mc->ng_textfield_idx = -1;
    // Default identity transform: HCALLOC zeros xscale/yscale, which makes the
    // level's local matrix have determinant 0 (since a=b=c=d=0). That zero
    // determinant propagates to all level-rooted descendants via
    // getConcatMatrixForMC, breaking world-coord drop-target hit tests for
    // them (e.g. _level50.target10 is skipped in actionFindDynamicDropTarget
    // because det==0). Set to 100% scale so the level acts as identity.
    mc->xscale = 100;
    mc->yscale = 100;
    // Same class of bug as the xscale/yscale zero above: HCALLOC leaves
    // `visible` at 0, so a freshly minted level root reads back as HIDDEN.
    // `_levelN._visible` is script-visible and wrong on its own, but it only
    // became load-bearing once AVM1 picking grew Ruffle's `if self.visible()`
    // gate (mouse_pick_avm1, movie_clip.rs:2995) — that walks the parent chain,
    // so every clip under a loaded level stopped receiving mouse events.
    // Repro: avm2/mouse_pick_avm1_root, whose AVM1 child lives under _level1.
    mc->visible = 1;
    g_levels[level_num] = mc;
    if (level_num > g_levels_high_water) g_levels_high_water = level_num;
    // Register in child_mc_cache so lookups find it
    if (child_mc_count < MAX_CHILD_MOVIECLIPS) {
        child_mc_cache[child_mc_count++] = mc;
    }
    return mc;
}

// Flash semantics: level roots (mc loaded into _levelN, including _root) have
// an empty `_name` even though `mc->name` holds "_levelN" for toString/path
// use. If a script (or MCL replace) has overridden the level MC's name to
// something other than the synthetic "_levelN", we honor the override and
// return that name instead.
static int isLevelRootMC(MovieClip* mc) {
    if (mc == NULL) return 0;
    int is_level = 0;
    if (mc == &root_movieclip) is_level = 1;
    else {
        for (int i = 1; i < MAX_LEVELS; i++) {
            if (g_levels[i] == mc) { is_level = 1; break; }
        }
    }
    if (!is_level) return 0;
    // Empty name: level root with default state → empty `_name`.
    if (mc->name[0] == '\0') return 1;
    // Matches the synthetic "_levelN" name we stamp in getOrCreateLevel /
    // root_movieclip's static init? If yes, treat as level-default → empty.
    // Otherwise (e.g. MCL replace stamped a real name), honor the override.
    if (strncmp(mc->name, "_level", 6) == 0) {
        for (size_t i = 6; mc->name[i] != '\0'; i++) {
            if (mc->name[i] < '0' || mc->name[i] > '9') return 0;
        }
        return 1;
    }
    return 0;
}

