static void installAsBroadcaster(SWFAppContext* app_context, ASObject* obj)
{
    initAsBroadcasterFuncs(app_context);

    // Ruffle marks these as DONT_ENUM (and methods also DONT_DELETE). Matching
    // those flags keeps AsBroadcaster methods out of for-in/_toXML
    // enumerations, matching Flash's observable behavior.
    const u8 listeners_flags = PROPERTY_FLAG_WRITABLE | PROPERTY_FLAG_CONFIGURABLE;
    const u8 method_flags    = PROPERTY_FLAG_WRITABLE;

    ASArray* listeners = allocArray(app_context, 4);
    ActionVar lv = {0};
    lv.type = ACTION_STACK_VALUE_ARRAY;
    lv.data.numeric_value = (u64)listeners;
    setPropertyWithFlags(app_context, obj, "_listeners", 10, &lv, listeners_flags);

    ActionVar fv = {0};
    fv.type = ACTION_STACK_VALUE_FUNCTION;

    fv.data.numeric_value = (u64)&g_ab_addListener_func;
    setPropertyWithFlags(app_context, obj, "addListener", 11, &fv, method_flags);

    fv.data.numeric_value = (u64)&g_ab_removeListener_func;
    setPropertyWithFlags(app_context, obj, "removeListener", 14, &fv, method_flags);

    fv.data.numeric_value = (u64)&g_ab_broadcastMessage_func;
    setPropertyWithFlags(app_context, obj, "broadcastMessage", 16, &fv, method_flags);
}

// See the forward declaration above initTextFieldPrototype.
static void installTextFieldBroadcaster(SWFAppContext* app_context, MovieClip* mc)
{
    // SWF5 MC textfields are not instanceof TextField and get no TextField
    // surface at all (see the __proto__ gates at every call site), so the
    // broadcaster is SWF6+ too.
    if (mc == NULL || g_swf_version < 6) return;
    ASObject* props = (ASObject*) mc->dynamic_props;
    if (props == NULL) return;
    // Idempotent: the clone/timeline paths can re-enter for the same field,
    // and re-initializing would drop listeners the script already added.
    if (getProperty(props, "_listeners", 10) != NULL) return;

    installAsBroadcaster(app_context, props);

    ActionVar* lp = getProperty(props, "_listeners", 10);
    if (lp == NULL || lp->type != ACTION_STACK_VALUE_ARRAY) return;
    ASArray* arr = (ASArray*) (uintptr_t) lp->data.numeric_value;
    if (arr == NULL) return;
    ActionVar self = {0};
    self.type = ACTION_STACK_VALUE_MOVIECLIP;
    VAL(u64, &self.data.numeric_value) = (u64) mc;
    setArrayElement(app_context, arr, 0, &self);
}

// Mark AsBroadcaster methods as SWF6+ (hidden in SWF5 via flash_flags).
// Called after installAsBroadcaster for objects like Key and Mouse where
// addListener/removeListener should not be visible in SWF5.
static void markAsBroadcasterSWF6(ASObject* obj)
{
    const char* names[] = {"addListener", "removeListener", "broadcastMessage", "_listeners"};
    const u32 lens[] = {11, 14, 16, 10};
    for (int i = 0; i < 4; i++) {
        for (u32 j = 0; j < obj->num_used; j++) {
            if (obj->properties[j].name_length == lens[i] &&
                strncmp(obj->properties[j].name, names[i], lens[i]) == 0) {
                obj->properties[j].flash_flags = 0x0080;
                break;
            }
        }
    }
}

// AsBroadcaster.initialize(obj) — static method callable from AS2.
// Installs _listeners, addListener, removeListener, broadcastMessage on the target.
static ActionVar builtin_asbroadcaster_initialize(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
    (void)registers; (void)this_obj;
    ActionVar undef = {0}; undef.type = ACTION_STACK_VALUE_UNDEFINED;
    if (arg_count < 1) return undef;

    ASObject* target = NULL;
    if (args[0].type == ACTION_STACK_VALUE_OBJECT || args[0].type == ACTION_STACK_VALUE_ARRAY) {
        target = (ASObject*)(uintptr_t)args[0].data.numeric_value;
    } else if (args[0].type == ACTION_STACK_VALUE_FUNCTION) {
        ASFunction* f = lookupFunctionFromVar(&args[0]);
        if (f && f->own_props) target = f->own_props;
    } else if (args[0].type == ACTION_STACK_VALUE_MOVIECLIP) {
        MovieClip* mc = (MovieClip*)(uintptr_t)args[0].data.numeric_value;
        // If the MC reference is stale (removeMovieClip + recreate at the
        // same name pattern), rebind it to the live MC at the same path so
        // `AsBroadcaster.initialize(staleRef)` after a recreate succeeds.
        // Mirrors Flash's "soft" MovieClip references (AsBroadcaster.as:173:
        // dang re-resolved to depth-2 'dangling' after removeMovieClip +
        // createEmptyMovieClip('dangling', 2)).
        if (mc != NULL) {
            mc = reResolveDeadBaseClip(app_context, mc);
        }
        if (mc != NULL && mc->dynamic_props == NULL && mc->depth != INT_MIN) {
            mc->dynamic_props = allocDynamicProps(app_context, 4);
        }
        if (mc && mc->dynamic_props) target = (ASObject*) mc->dynamic_props;
    }
    if (!target) return undef;

    installAsBroadcaster(app_context, target);
    return undef;
}

