			fn->advanced_func = (Function2Ptr) builtin_sound_getPan;
			if (function_count < MAX_FUNCTIONS) function_registry[function_count++] = fn;
			ActionVar fv = {0}; fv.type = ACTION_STACK_VALUE_FUNCTION; fv.data.numeric_value = (u64) fn;
