// ---------------------------------------------------------------------------
// XMLSocket (AVM1) — Ruffle core/src/avm1/globals/xml_socket.rs
// ---------------------------------------------------------------------------
//
// Per-instance native state hangs off a pointer-keyed side table, the same
// shape NetConnection/NetStream use above. The transport is the scripted mock
// in src/utils.c; with no socket.json loaded connect() still returns true (it
// always does — "we do not know yet whether the connection will succeed") but
// nothing is ever opened, so send/close stay silent no-ops.
//
// Inbound framing is the part the corpus actually grades (xml_socket_segmented,
// 29 lines): a chunk is appended to the read buffer and then COMPLETE
// NUL-terminated frames are split off the FRONT one at a time, each handed to
// onData without its NUL. The buffer is re-examined between calls because a
// handler may close the socket — which clears it, dropping anything still
// queued. A trailing unterminated fragment stays buffered and dies unfired at
// disconnect.

#define MAX_XMLSOCK_STATES 32
typedef struct
{
	ASObject* obj;
	SWFAppContext* app;   // captured at connect(); the mock callback has no ctx
	int handle;       // mock handle; 0 = never connected
	u32 timeout;
	char* buf;        // inbound bytes since the last complete frame
	size_t buf_len, buf_cap;
} XmlSockState;
static XmlSockState g_xmlsock_states[MAX_XMLSOCK_STATES];
static int g_xmlsock_state_count = 0;

static XmlSockState* xmlsock_find(ASObject* o)
{
	for (int i = 0; i < g_xmlsock_state_count; i++)
		if (g_xmlsock_states[i].obj == o) return &g_xmlsock_states[i];
	return NULL;
}

static XmlSockState* xmlsock_get(ASObject* o)
{
	XmlSockState* s = xmlsock_find(o);
	if (s != NULL) return s;
	if (g_xmlsock_state_count >= MAX_XMLSOCK_STATES) return NULL;
	s = &g_xmlsock_states[g_xmlsock_state_count++];
	memset(s, 0, sizeof(*s));
	s->obj = o;
	s->timeout = 20000;  // Ruffle's default
	return s;
}

static void xmlsock_buf_append(XmlSockState* s, const unsigned char* d, size_t n)
{
	if (s->buf_len + n > s->buf_cap)
	{
		size_t ncap = s->buf_cap ? s->buf_cap : 64;
		while (ncap < s->buf_len + n) ncap *= 2;
		char* nb = (char*) realloc(s->buf, ncap);
		if (nb == NULL) return;
		s->buf = nb;
		s->buf_cap = ncap;
	}
	memcpy(s->buf + s->buf_len, d, n);
	s->buf_len += n;
}

// Server -> player, delivered by the mock at the tick boundary.
static void xmlsock_dispatch(void* target, int action,
                             const unsigned char* data, size_t len)
{
	ASObject* sock = (ASObject*) target;
	if (sock == NULL) return;
	XmlSockState* s = xmlsock_find(sock);
	if (s == NULL || s->app == NULL) return;
	SWFAppContext* app_context = s->app;

	if (action == SWF_SOCKET_CONNECT)
	{
		ActionVar ok = {0};
		ok.type = ACTION_STACK_VALUE_BOOLEAN;
		ok.data.numeric_value = 1;
		soundFireCallback(app_context, sock, "onConnect", 9, &ok, 1);
		return;
	}
	if (action == SWF_SOCKET_CLOSE)
	{
		s->buf_len = 0;
		soundFireCallback(app_context, sock, "onClose", 7, NULL, 0);
		return;
	}
	if (action != SWF_SOCKET_DATA) return;

	xmlsock_buf_append(s, data, len);
	for (;;)
	{
		size_t pos = 0;
		while (pos < s->buf_len && s->buf[pos] != '\0') pos++;
		if (pos >= s->buf_len) break;  // no complete frame left
		ActionVar msg = makeStringActionVar(app_context, s->buf, (u32) pos);
		// Consume the frame (and its NUL) BEFORE the callback: the handler may
		// close the socket, which clears whatever is left.
		size_t rest = s->buf_len - (pos + 1);
		if (rest > 0) memmove(s->buf, s->buf + pos + 1, rest);
		s->buf_len = rest;
		soundFireCallback(app_context, sock, "onData", 6, &msg, 1);
	}
}

static ActionVar builtin_xmlsocket_connect(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void) registers;
	ActionVar ret = {0};
	ret.type = ACTION_STACK_VALUE_BOOLEAN;
	ret.data.numeric_value = 0;
	ASObject* sock = (ASObject*) this_obj;
	if (sock == NULL) return ret;
	XmlSockState* s = xmlsock_get(sock);
	if (s == NULL) return ret;

	// No host / null / undefined falls back to the movie URL's domain, which
	// for a file:// movie is "localhost" (Ruffle xml_socket.rs::connect).
	char host[512];
	if (arg_count < 1 || args[0].type == ACTION_STACK_VALUE_NULL
	    || args[0].type == ACTION_STACK_VALUE_UNDEFINED)
	{
		strcpy(host, "localhost");
	}
	else
	{
		int n = varToStringBufFull(app_context, &args[0], host, sizeof(host));
		if (n < 0) host[0] = '\0';
	}
	u32 port = 0;
	if (arg_count > 1)
	{
		double d = varToDoubleSimple(&args[1]);
		port = (u32) ecmaToInt32(d) & 0xFFFFu;  // ECMA ToUint16
	}

	s->app = app_context;
	int prev = s->handle;
	s->handle = swf_socket_connect(host, (int) port, sock, xmlsock_dispatch);
	if (prev != 0) swf_socket_close(prev);

	// Flash returns false when no connection is established and true
	// otherwise; Ruffle returns true unconditionally because connecting is
	// asynchronous and it cannot know yet (xml_socket.rs says so in a
	// comment). Our transport is a script, so we DO know synchronously —
	// no script means nothing was ever opened, which is Flash's false.
	// from_gnash/actionscript.all/XMLSocket-v{5,6,7,8} assert exactly this
	// (`socketObj.connect(host, port) == false` for an unreachable host) and
	// are `known_failure` upstream precisely because Ruffle answers true.
	ret.data.numeric_value = (s->handle != 0) ? 1 : 0;
	return ret;
}

static ActionVar builtin_xmlsocket_send(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void) registers;
	ActionVar ret = {0};
	ret.type = ACTION_STACK_VALUE_UNDEFINED;
	ASObject* sock = (ASObject*) this_obj;
	if (sock == NULL) return ret;
	XmlSockState* s = xmlsock_find(sock);
	// Never connected: a silent no-op (Ruffle guards on the handle).
	if (s == NULL || s->handle == 0) return ret;

	// toString(arg) plus a terminating NUL, sent immediately — one send() is
	// one message on the wire.
	char buf[8192];
	int n = 0;
	if (arg_count > 0) n = varToStringBufFull(app_context, &args[0], buf, sizeof(buf) - 1);
	else n = snprintf(buf, sizeof(buf), "undefined");
	if (n < 0) n = 0;
	buf[n] = '\0';
	swf_socket_send(s->handle, (const unsigned char*) buf, (size_t) n + 1);
	return ret;
}

static ActionVar builtin_xmlsocket_close(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void) app_context; (void) args; (void) arg_count; (void) registers;
	ActionVar ret = {0};
	ret.type = ACTION_STACK_VALUE_UNDEFINED;
	ASObject* sock = (ASObject*) this_obj;
	if (sock == NULL) return ret;
	XmlSockState* s = xmlsock_find(sock);
	if (s == NULL || s->handle == 0) return ret;
	swf_socket_close(s->handle);
	// close_internal clears the read buffer, so a frame still queued behind
	// the one being handled is discarded rather than delivered.
	s->buf_len = 0;
	return ret;
}

static ActionVar builtin_xmlsocket_getTimeout(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void) app_context; (void) args; (void) arg_count; (void) registers;
	ActionVar ret = {0};
	ret.type = ACTION_STACK_VALUE_F64;
	ASObject* sock = (ASObject*) this_obj;
	XmlSockState* s = (sock != NULL) ? xmlsock_get(sock) : NULL;
	double t = (s != NULL) ? (double) s->timeout : 20000.0;
	memcpy(&ret.data.numeric_value, &t, sizeof(double));
	return ret;
}

static ActionVar builtin_xmlsocket_setTimeout(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void) app_context; (void) registers;
	ActionVar ret = {0};
	ret.type = ACTION_STACK_VALUE_UNDEFINED;
	ASObject* sock = (ASObject*) this_obj;
	if (sock == NULL || arg_count < 1) return ret;
	XmlSockState* s = xmlsock_get(sock);
	// AVM1 does NOT clamp to 250ms — that floor is AS3 Socket's
	// (Ruffle xml_socket.rs carries a FIXME saying as much).
	if (s != NULL) s->timeout = (u32) ecmaToInt32(varToDoubleSimple(&args[0]));
	return ret;
}

// XMLSocket.prototype.onData default: parse the frame as XML and hand it to
// this.onXML. Assigning onData on the instance REPLACES this entirely, which
// is why xml_socket_on_data can assert onXML never runs.
static ActionVar builtin_xmlsocket_onData(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void) registers;
	ActionVar ret = {0};
	ret.type = ACTION_STACK_VALUE_UNDEFINED;
	ASObject* sock = (ASObject*) this_obj;
	if (sock == NULL) return ret;

	initXMLPrototype(app_context);
	ASObject* doc = xml_create_document(app_context);
	doc->native_type = NATIVE_XML;
	if (arg_count > 0 && args[0].type == ACTION_STACK_VALUE_STRING)
	{
		const uint16_t* u16 = varGetU16Ptr(&args[0]);
		u32 u16_len = args[0].str_size;
		char* buf = (char*) malloc((size_t) u16_len * 4 + 1);
		if (buf != NULL)
		{
			u32 utf8_len = (u32) u16_to_utf8(u16, u16_len, buf, u16_len * 4 + 1);
			xml_parse_into(app_context, doc, buf, utf8_len);
			free(buf);
		}
	}
	ActionVar xv = {0};
	xv.type = ACTION_STACK_VALUE_OBJECT;
	xv.data.numeric_value = (u64) doc;
	soundFireCallback(app_context, sock, "onXML", 5, &xv, 1);
	return ret;
}

// XMLSocket.prototype: 6 methods. The shape (names, order and flags) is
// exactly the stub's — global_instance_decls enumerates this family, so only
// the bodies changed.
static void addNativeMethodToProto(SWFAppContext* app_context, ASObject* proto,
                                   const char* name, u32 name_len, u8 flags,
                                   Function2Ptr impl)
{
	if (g_proto_stub_func_count >= MAX_PROTO_STUB_FUNCS) return;
	ASFunction* fn = &g_proto_stub_funcs[g_proto_stub_func_count++];
	memset(fn, 0, sizeof(ASFunction));
	strncpy(fn->name, name, 255);
	fn->function_type = 2;
	fn->advanced_func = impl;
	setupNativeFuncOwnProps(app_context, fn);
	if (function_count < MAX_FUNCTIONS) function_registry[function_count++] = fn;
	ActionVar fv = {0};
	fv.type = ACTION_STACK_VALUE_FUNCTION;
	fv.data.numeric_value = (u64) fn;
	setPropertyWithFlags(app_context, proto, name, name_len, &fv, flags);
}

static void initXMLSocketPrototype(SWFAppContext* app_context, ASFunction* ctor)
{
	if (ctor->prototype_obj != NULL) return;
	ctor->prototype_obj = allocObject(app_context, 8);
	retainObject(ctor->prototype_obj);
	// constructor first (enumerated last in LIFO)
	ActionVar ctor_var = {0};
	ctor_var.type = ACTION_STACK_VALUE_FUNCTION;
	ctor_var.data.numeric_value = (u64) ctor;
	setPropertyWithFlags(app_context, ctor->prototype_obj, "constructor", 11, &ctor_var, PROPERTY_FLAGS_DONTENUM);
	// __proto__ → Object.prototype (enumerated before constructor in LIFO)
	setObjectProto(app_context, ctor->prototype_obj);
	const u8 mflags = PROPERTY_FLAG_WRITABLE; // DONT_ENUM + DONT_DELETE
	addNativeMethodToProto(app_context, ctor->prototype_obj, "connect", 7, mflags,
	                       (Function2Ptr) builtin_xmlsocket_connect);
	addNativeMethodToProto(app_context, ctor->prototype_obj, "send", 4, mflags,
	                       (Function2Ptr) builtin_xmlsocket_send);
	addNativeMethodToProto(app_context, ctor->prototype_obj, "close", 5, mflags,
	                       (Function2Ptr) builtin_xmlsocket_close);
	addNativeMethodToProto(app_context, ctor->prototype_obj, "onData", 6, mflags,
	                       (Function2Ptr) builtin_xmlsocket_onData);
	addNativeMethodToProto(app_context, ctor->prototype_obj, "getTimeout", 10, mflags,
	                       (Function2Ptr) builtin_xmlsocket_getTimeout);
	addNativeMethodToProto(app_context, ctor->prototype_obj, "setTimeout", 10, mflags,
	                       (Function2Ptr) builtin_xmlsocket_setTimeout);
}

// ---------------------------------------------------------------------------
// flash.net.FileReference / FileReferenceList (AVM1)
// ---------------------------------------------------------------------------
//
// Ruffle: core/src/avm1/globals/file_reference{,_list}.rs plus the two
// select_*_file_dialog_avm1 halves of loader.rs. The dialog itself is the
// scripted mock in src/utils.c (dialog_events.h).
//
// Two things carry all the graded behaviour:
//
//  * Filter validation. `browse()` with no argument opens a dialog (with no
//    filters, so the mock cancels); `browse(x)` for any non-Object x, or for
//    an array that is empty / holds a non-Object / holds a filter missing an
//    OWN description or extension / holds an empty one, returns false without
//    opening anything. A field supplied by an addProperty GETTER counts as
//    own; a getter that throws is swallowed and the field reads as missing;
//    but an exception from `toString()` during the string coercion that
//    follows PROPAGATES to the script. file_reference_list_browse_invalid_filters
//    grades all eighteen cases.
//
//  * Delivery. Selection and cancellation arrive as AsBroadcaster messages —
//    `broadcastMessage("onSelect"/"onCancel", target)` — with the ONE argument
//    being the FileReference/FileReferenceList itself.
//
// The instance properties (name/type/size) are defined on SELECT, as own
// DONT_ENUM|READ_ONLY|DONT_DELETE props, which is where Flash keeps them
// (global_instance_decls). Before a selection they simply do not exist, so
// they read as undefined — which is exactly what the pre-browse and
// post-cancel dumps expect.

static ASObject* g_file_reference_prototype;  // set in initFlashPackage
static SWFAppContext* g_file_dialog_app;      // captured at browse()

// Coerce to a UTF-8 C string through the ordinary conversion path, so a
// throwing valueOf/toString unwinds to the script's try/catch the way it
// would from any other native.
static void filerefCoerceString(SWFAppContext* app_context, ActionVar* v,
                                char* out, size_t out_size)
{
	out[0] = '\0';
	pushVar(app_context, v);
	convertString(app_context, NULL);
	if (STACK_TOP_TYPE == ACTION_STACK_VALUE_STRING)
	{
		const uint16_t* u16 = (const uint16_t*) (uintptr_t) STACK_TOP_VALUE;
		u32 u16_len = STACK_TOP_N;
		u16_to_utf8(u16, u16_len, out, out_size);
	}
	POP();
}

// One filter field, read as an OWN property. Returns 0 when the field is
// absent — and also when an addProperty getter for it throws, because Ruffle
// swallows that (`object.get(name, activation).ok()`).
static int filerefOwnField(SWFAppContext* app_context, ASObject* el,
                           const char* name, u32 name_len, ActionVar* out)
{
	ASProperty* p = findPropertyRaw(el, name, name_len);
	if (p == NULL) return 0;
	if (p->getter == NULL)
	{
		*out = p->value;
		return 1;
	}

	u32 saved_sp = SP;
	u32 saved_scope = scope_depth;
	u32 saved_this = g_this_depth;
	int ed = g_exception_state.depth;
	if (ed >= MAX_EXCEPTION_DEPTH) return 0;
	g_exception_state.frames[ed].saved_scope_depth = scope_depth;
	g_exception_state.frames[ed].saved_sp = SP;
	g_exception_state.frames[ed].has_jmp_buf = 1;
	g_exception_state.depth = ed + 1;
	int ok = 0;
	if (setjmp(g_exception_state.frames[ed].handler) != 0)
	{
		// Getter threw: treat the field as missing, exactly like Ruffle.
		g_exception_state.exception_thrown = false;
		scope_depth = saved_scope;
		g_this_depth = saved_this;
		SP = saved_sp;
	}
	else
	{
		*out = invokeVirtualGetter(app_context, p, el);
		ok = 1;
	}
	g_exception_state.frames[ed].has_jmp_buf = 0;
	g_exception_state.depth = ed;
	return ok;
}

// Ruffle parse_file_filters + parse_file_filter_array. Returns 1 when a dialog
// should be opened (and sets *out_select from the magic description), 0 when
// browse() should just answer false.
static int filerefParseFilters(SWFAppContext* app_context, ActionVar* arg,
                               int* out_select)
{
	*out_select = 0;
	// No argument at all is valid and means "no filters"; any non-Object
	// argument (string, number, null, undefined) is not.
	if (arg == NULL) return 1;
	if (arg->type != ACTION_STACK_VALUE_ARRAY) return 0;
	ASArray* arr = (ASArray*) (uintptr_t) arg->data.numeric_value;
	if (arr == NULL || arr->length == 0) return 0;  // empty array is rejected

	for (u32 i = 0; i < arr->length; i++)
	{
		ActionVar* el_var = getArrayElement(arr, i);
		if (el_var == NULL || el_var->type != ACTION_STACK_VALUE_OBJECT) return 0;
		ASObject* el = (ASObject*) (uintptr_t) el_var->data.numeric_value;
		if (el == NULL) return 0;

		// All three fields are read BEFORE any of them is validated (Ruffle
		// destructures a tuple), so a throwing getter on one is swallowed even
		// when another is missing.
		ActionVar desc_v = {0}, ext_v = {0}, mac_v = {0};
		int has_desc = filerefOwnField(app_context, el, "description", 11, &desc_v);
		int has_ext = filerefOwnField(app_context, el, "extension", 9, &ext_v);
		int has_mac = filerefOwnField(app_context, el, "macType", 7, &mac_v);
		if (!has_desc || !has_ext) return 0;

		char desc[512], ext[512], mac[512];
		filerefCoerceString(app_context, &desc_v, desc, sizeof(desc));
		filerefCoerceString(app_context, &ext_v, ext, sizeof(ext));
		if (has_mac) filerefCoerceString(app_context, &mac_v, mac, sizeof(mac));

		if (desc[0] == '\0' || ext[0] == '\0') return 0;
		if (strcmp(desc, SWF_DIALOG_MAGIC_FILTER) == 0) *out_select = 1;
	}
	return 1;
}

// Ruffle's FileReferenceData carries an `is_initialised` flag and the selected
// file's bytes, neither of which is script-visible. Both matter to upload():
// uploading before a browse answers false, and onProgress reports the stored
// data's length. A pointer-keyed side table is the AVM1 idiom for this (the
// same shape NetConnection and XMLSocket use), and it keeps the instance's own
// property set exactly what global_instance_decls records.
#define MAX_FILEREF_STATE 32
typedef struct FileRefState
{
	ASObject* obj;
	u32 data_len;
} FileRefState;
static FileRefState g_fileref_state[MAX_FILEREF_STATE];
static int g_fileref_state_count;

static FileRefState* filerefStateFind(ASObject* obj)
{
	for (int i = 0; i < g_fileref_state_count; i++)
		if (g_fileref_state[i].obj == obj) return &g_fileref_state[i];
	return NULL;
}

static void filerefStateSet(ASObject* obj, u32 data_len)
{
	FileRefState* s = filerefStateFind(obj);
	if (s == NULL)
	{
		if (g_fileref_state_count >= MAX_FILEREF_STATE) return;
		s = &g_fileref_state[g_fileref_state_count++];
		s->obj = obj;
	}
	s->data_len = data_len;
}

// Adopt a simulated file onto a FileReference instance. `name` is the mock's
// for browse() and the SAVE HINT for download() — Ruffle's save dialog builds
// its TestFileSelection from the requested file name, which is why
// file_reference_download_success reports `debug-success.txt` and not
// `test.txt`.
static void filerefTakeSelectionNamed(SWFAppContext* app_context, ASObject* obj,
                                      const char* name, u32 size)
{
	// DONT_ENUM + READ_ONLY + DONT_DELETE — the flag set global_instance_decls
	// records for a real Flash FileReference's own name/type/size.
	const u8 ro = 0;
	ActionVar v;
	v = makeStringActionVar(app_context, name, (u32) strlen(name));
	setPropertyWithFlags(app_context, obj, "name", 4, &v, ro);
	v = makeStringActionVar(app_context, SWF_DIALOG_FILE_TYPE,
	                        (u32) strlen(SWF_DIALOG_FILE_TYPE));
	setPropertyWithFlags(app_context, obj, "type", 4, &v, ro);
	memset(&v, 0, sizeof(v));
	v.type = ACTION_STACK_VALUE_F64;
	{ double d = (double) size; memcpy(&v.data.numeric_value, &d, sizeof(double)); }
	setPropertyWithFlags(app_context, obj, "size", 4, &v, ro);
	filerefStateSet(obj, size);
}

static void filerefTakeSelection(SWFAppContext* app_context, ASObject* obj,
                                 int name_index)
{
	filerefTakeSelectionNamed(app_context, obj, swf_dialog_file_name(name_index),
	                          SWF_DIALOG_CONTENTS_LEN);
}

static void filerefBroadcast(SWFAppContext* app_context, ASObject* obj,
                             const char* event)
{
	ActionVar bargs[2];
	bargs[0] = makeStringActionVar(app_context, event, (u32) strlen(event));
	memset(&bargs[1], 0, sizeof(ActionVar));
	bargs[1].type = ACTION_STACK_VALUE_OBJECT;
	bargs[1].data.numeric_value = (u64) obj;
	builtin_broadcaster_broadcastMessage(app_context, bargs, 2, NULL, (void*) obj);
}

static void filerefDialogResolve(void* target, int success)
{
	ASObject* obj = (ASObject*) target;
	SWFAppContext* app_context = g_file_dialog_app;
	if (obj == NULL || app_context == NULL) return;
	if (success) filerefTakeSelection(app_context, obj, 0);
	filerefBroadcast(app_context, obj, success ? "onSelect" : "onCancel");
}

static void filereflistDialogResolve(void* target, int success)
{
	ASObject* obj = (ASObject*) target;
	SWFAppContext* app_context = g_file_dialog_app;
	if (obj == NULL || app_context == NULL) return;
	if (success)
	{
		// The multi-select mock hands back three files. `fileList` appears
		// only on select — it stays undefined through a cancel, which
		// file_reference_list_browse_cancel grades.
		ASArray* list = allocArray(app_context, 3);
		for (int i = 0; i < 3; i++)
		{
			ASObject* fr = allocObject(app_context, 8);
			if (fr == NULL) continue;
			retainObject(fr);
			fr->native_type = NATIVE_FILEREF;
			if (g_file_reference_prototype != NULL)
			{
				ActionVar pv = {0};
				pv.type = ACTION_STACK_VALUE_OBJECT;
				pv.data.numeric_value = (u64) g_file_reference_prototype;
				setPropertyWithFlags(app_context, fr, "__proto__", 9, &pv,
				                     PROPERTY_FLAG_WRITABLE);
			}
			filerefTakeSelection(app_context, fr, i + 1);
			ActionVar fv = {0};
			fv.type = ACTION_STACK_VALUE_OBJECT;
			fv.data.numeric_value = (u64) fr;
			setArrayElement(app_context, list, (u32) i, &fv);
		}
		ActionVar lv = {0};
		lv.type = ACTION_STACK_VALUE_ARRAY;
		lv.data.numeric_value = (u64) list;
		// READ_ONLY | DONT_ENUM | DONT_DELETE (loader.rs define_value).
		setPropertyWithFlags(app_context, obj, "fileList", 8, &lv, 0);
	}
	filerefBroadcast(app_context, obj, success ? "onSelect" : "onCancel");
}

// The two browse()s differ only in which dialog they open — single-file for a
// FileReference, multi-file for a FileReferenceList — so they share
// everything up to the queue call.
static ActionVar filerefBrowseCommon(SWFAppContext* app_context, ActionVar* args,
                                     u32 arg_count, void* this_obj,
                                     SwfDialogResolveFn resolve)
{
	ActionVar ret = {0};
	ret.type = ACTION_STACK_VALUE_BOOLEAN;
	ret.data.numeric_value = 0;
	ASObject* obj = (ASObject*) this_obj;
	if (obj == NULL) return ret;

	int select = 0;
	if (!filerefParseFilters(app_context, arg_count > 0 ? &args[0] : NULL, &select))
		return ret;

	g_file_dialog_app = app_context;
	// The pending dialog is the only reference the mock holds, so the target
	// has to outlive the frame that opened it.
	retainObject(obj);
	swf_dialog_queue(resolve, obj, select);
	ret.data.numeric_value = 1;
	return ret;
}

static ActionVar builtin_fileref_browse(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void) registers;
	return filerefBrowseCommon(app_context, args, arg_count, this_obj,
	                           filerefDialogResolve);
}

static ActionVar builtin_filereflist_browse(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void) registers;
	return filerefBrowseCommon(app_context, args, arg_count, this_obj,
	                           filereflistDialogResolve);
}

// ---------------------------------------------------------------------------
// FileReference.download / FileReference.upload
// ---------------------------------------------------------------------------
//
// Ruffle: file_reference.rs::{download,upload} plus loader.rs::
// {download_file_dialog,upload_file}. Each is ONE future — download awaits the
// save dialog and THEN the fetch, firing every callback in a single update —
// so the whole sequence runs inside one resolution callback here, and the
// dialog queue's ordinary pump is all the scheduling either needs. upload()
// opens no dialog at all; it rides the same queue purely to be async, which is
// what puts its events after the onSelect handler that started it.
//
// The transport is the test navigator's three magic query strings
// (tests/framework/src/backends/navigator.rs): "?debug-success" answers
// "Hello, World!", "?debug-error-statuscode" is an HttpNotOk with a zero-length
// body, "?debug-error-dns" an InvalidDomain. Anything else would be a real
// fetch, which for these two entry points can only fail.

enum
{
	FR_FETCH_OK = 0,
	FR_FETCH_STATUS,     // Error::HttpNotOk
	FR_FETCH_DNS,        // Error::InvalidDomain
	FR_FETCH_ERROR       // Error::FetchError
};

static int filerefClassifyUrl(const char* url)
{
	if (strstr(url, "?debug-success") != NULL) return FR_FETCH_OK;
	if (strstr(url, "?debug-error-statuscode") != NULL) return FR_FETCH_STATUS;
	if (strstr(url, "?debug-error-dns") != NULL) return FR_FETCH_DNS;
	return FR_FETCH_ERROR;
}

// Rust url::Url::parse, only as far as the corpus needs it: an absolute URL
// must start with a scheme. "@" and "baddomain" have none, and that is the
// whole of download()'s two false cases. The path is returned because a
// download with no explicit file name derives one from its last segment; note
// Url normalizes an empty path to "/" for the special schemes, so
// download("http://example.com") derives the EMPTY name (and the save dialog
// then cancels, which is file_reference_download_cancel).
static int filerefParseUrl(const char* url, char* out_scheme, size_t scheme_size,
                           char* out_path, size_t path_size)
{
	if (url == NULL || !isalpha((unsigned char) url[0])) return 0;
	size_t i = 0;
	while (url[i] != '\0' && url[i] != ':')
	{
		char c = url[i];
		if (!isalnum((unsigned char) c) && c != '+' && c != '-' && c != '.') return 0;
		i++;
	}
	if (url[i] != ':') return 0;
	if (out_scheme != NULL && scheme_size > 0)
	{
		size_t n = i < scheme_size - 1 ? i : scheme_size - 1;
		for (size_t k = 0; k < n; k++)
			out_scheme[k] = (char) tolower((unsigned char) url[k]);
		out_scheme[n] = '\0';
	}
	const char* p = url + i + 1;
	if (p[0] == '/' && p[1] == '/')
	{
		p += 2;   // skip the authority
		while (*p != '\0' && *p != '/' && *p != '?' && *p != '#') p++;
	}
	const char* end = p;
	while (*end != '\0' && *end != '?' && *end != '#') end++;
	if (out_path != NULL && path_size > 0)
	{
		size_t n = (size_t) (end - p);
		if (n >= path_size) n = path_size - 1;
		memcpy(out_path, p, n);
		out_path[n] = '\0';
	}
	return 1;
}

// One in-flight download/upload. The dialog queue carries only
// (callback, target, code), so the URL and the derived file name travel in a
// slot the callback is handed as its target.
#define MAX_FILEREF_OPS 8
typedef struct FileRefOp
{
	int in_use;
	ASObject* obj;
	char url[512];
	char file_name[256];
	u32 data_len;
} FileRefOp;
static FileRefOp g_fileref_ops[MAX_FILEREF_OPS];

static FileRefOp* filerefOpAlloc(void)
{
	for (int i = 0; i < MAX_FILEREF_OPS; i++)
	{
		if (g_fileref_ops[i].in_use) continue;
		memset(&g_fileref_ops[i], 0, sizeof(FileRefOp));
		g_fileref_ops[i].in_use = 1;
		return &g_fileref_ops[i];
	}
	return NULL;
}

static void filerefBroadcastProgress(SWFAppContext* app_context, ASObject* obj,
                                     u32 loaded, u32 total)
{
	ActionVar bargs[4];
	bargs[0] = makeStringActionVar(app_context, "onProgress", 10);
	memset(&bargs[1], 0, sizeof(ActionVar));
	bargs[1].type = ACTION_STACK_VALUE_OBJECT;
	bargs[1].data.numeric_value = (u64) obj;
	for (int i = 0; i < 2; i++)
	{
		memset(&bargs[2 + i], 0, sizeof(ActionVar));
		bargs[2 + i].type = ACTION_STACK_VALUE_F64;
		double d = (double) (i == 0 ? loaded : total);
		memcpy(&bargs[2 + i].data.numeric_value, &d, sizeof(double));
	}
	builtin_broadcaster_broadcastMessage(app_context, bargs, 4, NULL, (void*) obj);
}

// loader.rs::download_file_dialog. `code` is the mock's dialog verdict.
static void filerefDownloadResolve(void* target, int code)
{
	FileRefOp* op = (FileRefOp*) target;
	SWFAppContext* app_context = g_file_dialog_app;
	if (op == NULL) return;
	ASObject* obj = op->obj;
	if (obj == NULL || app_context == NULL) { op->in_use = 0; return; }

	if (!code)
	{
		filerefBroadcast(app_context, obj, "onCancel");
		op->in_use = 0;
		return;
	}

	// onSelect and onOpen are fired against the INITIAL dialog result, before
	// the download has produced anything.
	filerefTakeSelectionNamed(app_context, obj, op->file_name,
	                          SWF_DIALOG_CONTENTS_LEN);
	filerefBroadcast(app_context, obj, "onSelect");

	switch (filerefClassifyUrl(op->url))
	{
	case FR_FETCH_OK:
		filerefBroadcast(app_context, obj, "onOpen");
		// write_and_refresh + a second init_from_file_selection: onProgress and
		// onComplete see the DOWNLOADED bytes, not the placeholder.
		filerefTakeSelectionNamed(app_context, obj, op->file_name,
		                          SWF_DIALOG_CONTENTS_LEN);
		filerefBroadcastProgress(app_context, obj, SWF_DIALOG_CONTENTS_LEN,
		                         SWF_DIALOG_CONTENTS_LEN);
		filerefBroadcast(app_context, obj, "onComplete");
		break;
	case FR_FETCH_DNS:
		// The connection never opened, so there is no onOpen.
		printf("Error opening URL '%s'\n", op->url);
		filerefBroadcast(app_context, obj, "onIOError");
		break;
	case FR_FETCH_STATUS:
		filerefBroadcast(app_context, obj, "onOpen");
		printf("Error opening URL '%s'\n", op->url);
		filerefBroadcast(app_context, obj, "onIOError");
		// Flash still runs onProgress after an error, but only when the
		// connection had been established. HttpNotOk carries the error body's
		// length, which the test navigator sets to 0.
		filerefBroadcastProgress(app_context, obj, 0, 0);
		break;
	default:
		filerefBroadcast(app_context, obj, "onOpen");
		printf("Error opening URL '%s'\n", op->url);
		filerefBroadcast(app_context, obj, "onIOError");
		break;
	}
	op->in_use = 0;
}

// loader.rs::upload_file. onOpen is unconditional — it precedes the match on
// the fetch result.
static void filerefUploadResolve(void* target, int code)
{
	FileRefOp* op = (FileRefOp*) target;
	SWFAppContext* app_context = g_file_dialog_app;
	if (op == NULL) return;
	ASObject* obj = op->obj;
	if (obj == NULL || app_context == NULL) { op->in_use = 0; return; }

	filerefBroadcast(app_context, obj, "onOpen");
	switch (code)
	{
	case FR_FETCH_OK:
		filerefBroadcastProgress(app_context, obj, op->data_len, op->data_len);
		filerefBroadcast(app_context, obj, "onComplete");
		break;
	case FR_FETCH_STATUS:
		filerefBroadcastProgress(app_context, obj, op->data_len, op->data_len);
		filerefBroadcast(app_context, obj, "onHTTPError");
		break;
	default:
		// InvalidDomain, and a plain fetch error, both surface as onIOError.
		filerefBroadcast(app_context, obj, "onIOError");
		break;
	}
	op->in_use = 0;
}

static ActionVar builtin_fileref_download(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void) registers;
	ActionVar ret = {0};
	ret.type = ACTION_STACK_VALUE_BOOLEAN;
	ret.data.numeric_value = 0;
	ASObject* obj = (ASObject*) this_obj;
	if (obj == NULL || arg_count == 0) return ret;

	char url[512], path[512], file_name[256];
	filerefCoerceString(app_context, &args[0], url, sizeof(url));
	if (!filerefParseUrl(url, NULL, 0, path, sizeof(path))) return ret;

	if (arg_count > 1)
	{
		filerefCoerceString(app_context, &args[1], file_name, sizeof(file_name));
	}
	else
	{
		const char* last = path;
		for (const char* q = path; *q != '\0'; q++)
			if (*q == '/') last = q + 1;
		snprintf(file_name, sizeof(file_name), "%s", last);
	}

	FileRefOp* op = filerefOpAlloc();
	if (op == NULL) return ret;
	op->obj = obj;
	snprintf(op->url, sizeof(op->url), "%s", url);
	snprintf(op->file_name, sizeof(op->file_name), "%s", file_name);

	g_file_dialog_app = app_context;
	retainObject(obj);
	// The save dialog's verdict is the file-name hint, exactly as in browse().
	swf_dialog_queue(filerefDownloadResolve, op,
	                 strcmp(file_name, SWF_DIALOG_MAGIC_SAVE) == 0);
	ret.data.numeric_value = 1;   // the dialog was displayed
	return ret;
}

static ActionVar builtin_fileref_upload(SWFAppContext* app_context, ActionVar* args, u32 arg_count, ActionVar* registers, void* this_obj)
{
	(void) registers;
	ActionVar ret = {0};
	ret.type = ACTION_STACK_VALUE_BOOLEAN;
	ret.data.numeric_value = 0;
	ASObject* obj = (ASObject*) this_obj;
	if (obj == NULL) return ret;

	// Nothing browsed yet means nothing to upload.
	FileRefState* st = filerefStateFind(obj);
	if (st == NULL || arg_count == 0) return ret;

	char url[512], scheme[16];
	filerefCoerceString(app_context, &args[0], url, sizeof(url));
	if (!filerefParseUrl(url, scheme, sizeof(scheme), NULL, 0)) return ret;
	if (strcmp(scheme, "http") != 0 && strcmp(scheme, "https") != 0) return ret;

	FileRefOp* op = filerefOpAlloc();
	if (op == NULL) return ret;
	op->obj = obj;
	op->data_len = st->data_len;
	snprintf(op->url, sizeof(op->url), "%s", url);

	g_file_dialog_app = app_context;
	retainObject(obj);
	swf_dialog_queue(filerefUploadResolve, op, filerefClassifyUrl(url));
	ret.data.numeric_value = 1;
	return ret;
}

// Install the AsBroadcaster trio + a real zero-length `_listeners` Array on a
// prototype, WITHOUT touching the property shape the stub established:
// global_proto_decls and global_proto_decls_delete enumerate this family, so
// the names, their order and their DONT_ENUM|DONT_DELETE flags all have to
// stay byte-identical — only the values change. (installAsBroadcaster is not
// reusable here: it makes `_listeners` deletable.)
static void filerefInstallBroadcaster(SWFAppContext* app_context, ASObject* proto)
{
	initAsBroadcasterFuncs(app_context);
	const u8 f = PROPERTY_FLAG_WRITABLE;  // DONT_ENUM + DONT_DELETE

	// Insertion is LIFO relative to enumeration, so this is the reverse of the
	// expected `_listeners, removeListener, addListener, broadcastMessage`.
	ActionVar fv = {0};
	fv.type = ACTION_STACK_VALUE_FUNCTION;
	fv.data.numeric_value = (u64) &g_ab_broadcastMessage_func;
	setPropertyWithFlags(app_context, proto, "broadcastMessage", 16, &fv, f);
	fv.data.numeric_value = (u64) &g_ab_addListener_func;
	setPropertyWithFlags(app_context, proto, "addListener", 11, &fv, f);
	fv.data.numeric_value = (u64) &g_ab_removeListener_func;
	setPropertyWithFlags(app_context, proto, "removeListener", 14, &fv, f);

	ASArray* listeners = allocArray(app_context, 4);
	ActionVar lv = {0};
	lv.type = ACTION_STACK_VALUE_ARRAY;
	lv.data.numeric_value = (u64) listeners;
	setPropertyWithFlags(app_context, proto, "_listeners", 10, &lv, f);
}

// ContextMenu.prototype: copy + hideBuiltInItems
static ASFunction g_cm_copy_func;
static ASFunction g_cm_hideBuiltIn_func;
static void initContextMenuPrototype(SWFAppContext* app_context, ASFunction* ctor)
{
	if (ctor->prototype_obj != NULL) return;
	ctor->prototype_obj = allocObject(app_context, 4);
	retainObject(ctor->prototype_obj);
	// constructor first (enumerated last in LIFO)
	ActionVar ctor_var = {0};
	ctor_var.type = ACTION_STACK_VALUE_FUNCTION;
	ctor_var.data.numeric_value = (u64) ctor;
	setPropertyWithFlags(app_context, ctor->prototype_obj, "constructor", 11, &ctor_var, PROPERTY_FLAGS_DONTENUM);
	// __proto__ → Object.prototype (enumerated before constructor in LIFO)
	setObjectProto(app_context, ctor->prototype_obj);
	const u8 mflags = PROPERTY_FLAG_WRITABLE; // DONT_ENUM + DONT_DELETE
	// Real copy() implementation
	memset(&g_cm_copy_func, 0, sizeof(ASFunction));
	strncpy(g_cm_copy_func.name, "copy", 255);
	g_cm_copy_func.function_type = 2;
	g_cm_copy_func.advanced_func = (Function2Ptr) builtin_contextmenu_copy;
	setupNativeFuncOwnProps(app_context, &g_cm_copy_func);
	if (function_count < MAX_FUNCTIONS) function_registry[function_count++] = &g_cm_copy_func;
	ActionVar fv = {0};
	fv.type = ACTION_STACK_VALUE_FUNCTION;
	fv.data.numeric_value = (u64) &g_cm_copy_func;
	setPropertyWithFlags(app_context, ctor->prototype_obj, "copy", 4, &fv, mflags);
	// Real hideBuiltInItems() implementation
	memset(&g_cm_hideBuiltIn_func, 0, sizeof(ASFunction));
	strncpy(g_cm_hideBuiltIn_func.name, "hideBuiltInItems", 255);
	g_cm_hideBuiltIn_func.function_type = 2;
	g_cm_hideBuiltIn_func.advanced_func = (Function2Ptr) builtin_contextmenu_hideBuiltInItems;
	setupNativeFuncOwnProps(app_context, &g_cm_hideBuiltIn_func);
	if (function_count < MAX_FUNCTIONS) function_registry[function_count++] = &g_cm_hideBuiltIn_func;
	ActionVar hv = {0};
	hv.type = ACTION_STACK_VALUE_FUNCTION;
	hv.data.numeric_value = (u64) &g_cm_hideBuiltIn_func;
	setPropertyWithFlags(app_context, ctor->prototype_obj, "hideBuiltInItems", 16, &hv, mflags);
}

