					ActionVar* _np = getProperty(_cur, "__proto__", 9);
					if (_np == NULL || _np->type != ACTION_STACK_VALUE_OBJECT || _np->data.numeric_value == 0) break;
					ASObject* _next = (ASObject*) _np->data.numeric_value;
