							int _am_ver4 = _am_exp_ver4 ? _am_exp_ver4 : ((mc && mc->swf_version) ? mc->swf_version : g_swf_version);
							void* _am_reg_ctor2 = lookupRegisteredClassVersion(linkage_id, _am_ver4);
